codeExamples.code:
-- Remove a table permanently (errors if it does not exist)
DROP TABLE staging_orders;

-- Safe, idempotent form for scripts
DROP TABLE IF EXISTS staging_orders;

-- MySQL allows dropping multiple tables at once
DROP TABLE IF EXISTS tmp_a, tmp_b, tmp_c;

-- This fails if orders.customer_id references customers(customer_id)
DROP TABLE customers;
-- ERROR: cannot drop table customers because other objects depend on it

-- PostgreSQL: drop the table and dependent FK constraints/views
DROP TABLE customers CASCADE;

-- MySQL approach: drop children first, or disable FK checks temporarily
DROP TABLE orders;            -- child first
DROP TABLE customers;         -- then parent

-- MySQL alternative (use with caution):
SET FOREIGN_KEY_CHECKS = 0;
DROP TABLE customers;
SET FOREIGN_KEY_CHECKS = 1;

-- MySQL / Oracle: DROP issues an IMPLICIT COMMIT
START TRANSACTION;
INSERT INTO audit_log (msg) VALUES ('before drop');
DROP TABLE temp_data;   -- implicitly commits the INSERT too
ROLLBACK;               -- has no effect; the INSERT and DROP are already committed

-- PostgreSQL: DDL is transactional
BEGIN;
DROP TABLE temp_data;
ROLLBACK;               -- temp_data still exists; the drop was undone
